<script setup>
import { computed,ref,watch } from 'vue';
import { fdate,ftime,num } from '../../lib/client-info';
const props=defineProps({bundle:Object,metrics:Object});
const plan=ref(''),shown=ref(16);
const plans=computed(()=>[...new Set(props.bundle.sessions.map(row=>row.therapy_plan).filter(Boolean))]);
const filtered=computed(()=>props.bundle.sessions.filter(row=>!plan.value||row.therapy_plan===plan.value));
const weights=computed(()=>props.bundle.sessions.filter(row=>num(row.before_weight)>0).sort((a,b)=>String(a.start_date).localeCompare(String(b.start_date))));
const weightChange=computed(()=>{const rows=weights.value;return rows.length>1?Math.round(((num(rows.at(-1).after_weight)||num(rows.at(-1).before_weight))-num(rows[0].before_weight))*10)/10:null;});
const stats=computed(()=>[['💆','Total',props.bundle.sessions.length],['✅','Submitted',props.bundle.sessions.filter(row=>Number(row.docstatus)===1).length],['📝','Draft',props.bundle.sessions.filter(row=>Number(row.docstatus)===0).length],['📆','Avg / month',props.metrics.avgMonthly.toFixed(1)],[weightChange.value===null?'🕒':'⚖️',weightChange.value===null?'Last session':'Weight change',weightChange.value===null?fdate(props.metrics.last):(weightChange.value>0?'+':'')+weightChange.value+' kg']]);
watch(plan,()=>{shown.value=16;});
</script>
<template><div><div class="c3-kpis"><div v-for="row in stats" :key="row[1]" class="c3-kpi"><span class="c3-kpi-ic">{{ row[0] }}</span><div><small>{{ row[1] }}</small><b>{{ row[2] }}</b></div></div></div><div class="c3-filters"><label class="c3-select-l">📋 <select v-model="plan" aria-label="Session plan"><option value="">All plans</option><option v-for="value in plans" :key="value">{{ value }}</option></select></label></div><div class="c3-cards c3-c4"><article v-for="row in filtered.slice(0,shown)" :key="row.name" class="c3-card c3-ses"><header class="c3-card-h"><div><b>{{ row.name }}</b><small>📅 {{ fdate(row.start_date) }} {{ row.start_time?'🕐 '+ftime(row.start_time):'' }}</small></div><span class="c3-pill" :class="Number(row.docstatus)===1?'tone-ok':'tone-warn'">{{ Number(row.docstatus)===1?'✅ Submitted':'📝 Draft' }}</span></header><div class="c3-field f-green"><small>💆 Therapy</small><b>{{ row.therapy_type||'—' }}</b></div><div class="c3-field f-blue"><small>📋 Plan</small><b>{{ row.therapy_plan||'—' }}</b></div><div class="c3-field f-amber"><small>👩‍⚕️ Attended by</small><b>{{ row.custom_practitioner_name||row.practitioner||'—' }}</b></div><div class="c3-grid c3-g2"><div class="c3-field f-purple"><small>⏱ Duration</small><b>{{ row.duration||'—' }} min</b></div><div class="c3-field f-teal"><small>🏢 Branch</small><b>{{ row.branch||'—' }}</b></div></div><div v-if="row.before_weight||row.after_weight" class="c3-field f-rose"><small>⚖️ Weight</small><b>{{ row.before_weight||'—' }} → {{ row.after_weight||'—' }} <span v-if="num(row.weight_loss)" :class="num(row.weight_loss)>0?'tone-ok':'tone-neg'">({{ num(row.weight_loss)>0?'−':'+' }}{{ Math.abs(num(row.weight_loss)) }})</span></b></div></article></div><div v-if="filtered.length>shown" class="c3-more-wrap"><button type="button" class="c3-btn" @click="shown+=16">Show more sessions</button></div><div v-if="!filtered.length" class="c3-empty-sm">No therapy sessions.</div></div></template>
